    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzzed params: _baseToken and an arbitrary feeRate to keep admissible domain
    function testFuzz_property(address _baseToken, uint16 _feeRate) public {
        // keep feeRate in admissible range (0..6000) but especially <=5000 for normal path
        _feeRate = uint16(_feeRate % 6001);

        // choose some other params arbitrarily; keep _nft as a non-zero address for realism
        address _nft = address(0x1234);
        uint128 _virtualBaseTokenReserves = 1;
        uint128 _virtualNftReserves = 1;
        uint56 _changeFee = 0;
        bytes32 _merkleRoot = bytes32(0);
        bool _useStolenNftOracle = false;
        bool _payRoyalties = false;

        bool ok;
        // call initialize with fuzzed _baseToken and _feeRate
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // single assertion: if initialization succeeded, the stored baseToken equals the passed-in _baseToken.
        // This is true for the reference implementation for all inputs; the mutant that forces baseToken = address(0)
        // will cause this to fail when _baseToken != address(0) and initialize returns successfully.
        if (ok) {
