pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzzed params: _virtualBaseTokenReserves is the deciding value that should be preserved by initialize
    function testFuzz_property(uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties, address _baseToken, address _nft) public {
        // keep wide domain but enforce admissible constraints used in initialize: feeRate <= 5000
        vm.assume(_feeRate <= type(uint56).max);
        vm.assume(_changeFee <= type(uint56).max);
        vm.assume(_feeRate <= 5000);

        // Call initialize as an arbitrary caller (the reference implementation should accept any caller)
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            // If initialize reverts (e.g., called twice) mark as not ok. For freshly deployed c it should succeed.
            ok = false;
        }

        // If initialize failed, we cannot make the invariant claim about state; skip those cases by assuming it succeeded.
        vm.assume(ok);

        // Exactly one assertion: the reference preserves the passed in _virtualBaseTokenReserves
        assertTrue(c.virtualBaseTokenReserves() == _virtualBaseTokenReserves);
    }
}
